style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Fundo fixo com a imagem enviada */
  body, html {
    background: url("https://files.oaiusercontent.com/file_0000000065b071f5af2844cc15e060c5") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    color: #fff !important;
    filter: grayscale(100%) !important;
  }

  /* Remove o efeito preto e branco das imagens e avatares */
  img, .thumbnail-2d, .avatar, .thumbnail {
    filter: none !important;
  }

  /* Remove fundos sólidos das seções pra deixar o fundo visível */
  div, section, main, header, footer, nav, aside {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Ajusta texto pra ficar legível */
  * {
    color: #ffffff !important;
  }

  /* Ajusta links e botões */
  a, .btn, button {
    color: #ffffff !important;
    background: rgba(0, 0, 0, 0.4) !important;
    border: none !important;
  }

  /* Deixa o fundo do menu e cabeçalhos translúcido */
  header, nav, .navbar, .site-header {
    background: rgba(0, 0, 0, 0.4) !important;
    backdrop-filter: blur(6px) !important;
  }
}
